// friday13.cs — Friday the 13th in the proleptic Gregorian calendar
#:property PublishAot=false

// Find the earliest Friday the 13th starting from 0001-01-01
var earliest = DateOnly.MinValue; // 0001-01-01
var date = new DateOnly(1, 1, 13); // start checking the 13th of each month

DateOnly? firstFriday13 = null;
while (date.Year <= 400)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        firstFriday13 ??= date;
        break;
    }
    date = date.AddMonths(1);
}

Console.WriteLine($"Earliest Friday the 13th: {firstFriday13:yyyy-MM-dd} ({firstFriday13:dddd})");

// Count all Friday the 13ths in a full 400-year cycle (years 1–400)
int count = 0;
var d = new DateOnly(1, 1, 13);
while (d.Year <= 400)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
    d = d.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

